index 00000000..082d793b
--- /dev/null
+++ b/fuzz/fuzz_type_object/fuzz_type_object.c
@@ -0,0 +1,107 @@
+/*
+ * Copyright(c) 2021 to 2022 ZettaScale Technology and others
+ *
